using System.Security.Claims;
using CoracaoAnimal.Core;
using CoracaoAnimal.Api.Application;
using CoracaoAnimal.Api.Infrastructure;
using Microsoft.EntityFrameworkCore;
namespace CoracaoAnimal.Api;
public static class Endpoints {
 public static AnimalDto AnimalDto(Animal a)=>new(a.Id,a.Nome,a.Especie,a.Raca,a.Idade,a.Porte,a.Status,a.Descricao,a.FotoUrl);
 public static DoacaoDto DoacaoDto(Doacao d,bool admin=false)=>new(d.Id,d.Valor,d.FormaPagamento,d.Status,d.Descricao,d.Anonima,d.CriadoEm,admin?d.Adotante.Usuario.Nome:null);
 public static VoluntarioDto VoluntarioDto(Voluntario v,bool admin=false)=>new(v.Id,v.Area,v.Disponibilidade,v.Status,v.CriadoEm,admin?v.Usuario.Nome:null,admin?v.Usuario.Email:null);
 public static void MapApi(this WebApplication app){
  var api=app.MapGroup("/api");
  api.MapGet("/resumo",async(AppDb db)=>{
   var now=DateTime.UtcNow;var start=new DateTime(now.Year,1,1);var month=new DateTime(now.Year,now.Month,1);var end=start.AddYears(1);var nextMonth=month.AddMonths(1);
   var total=await db.Animais.CountAsync(x=>!x.Arquivado);var adopted=await db.Animais.CountAsync(x=>!x.Arquivado&&x.Status=="adotado");
   var dates=await db.Adocoes.Where(x=>x.Status=="concluida"&&x.AtualizadoEm>=start&&x.AtualizadoEm<end).Select(x=>x.AtualizadoEm).ToListAsync();
   var donations=await db.Doacoes.Where(x=>x.Status=="confirmada"&&x.CriadoEm>=start&&x.CriadoEm<end).Select(x=>new{x.CriadoEm,x.Valor}).ToListAsync();
   return new{ano=now.Year,totalAnimais=total,disponiveis=await db.Animais.CountAsync(x=>!x.Arquivado&&x.Status=="disponivel"),adocoesConcluidas=await db.Adocoes.CountAsync(x=>x.Status=="concluida"),adocoesMes=dates.Count(x=>x>=month&&x<nextMonth),adotantes=await db.Adotantes.CountAsync(),doacoesConfirmadas=(await db.Doacoes.Where(x=>x.Status=="confirmada").Select(x=>x.Valor).ToListAsync()).Sum(),taxa=total==0?0:Math.Round(adopted*100.0/total),adocoesPorMes=Enumerable.Range(1,12).Select(m=>dates.Count(x=>x.Month==m)).ToArray(),doacoesPorMes=Enumerable.Range(1,12).Select(m=>donations.Where(x=>x.CriadoEm.Month==m).Sum(x=>x.Valor)).ToArray()};
  });
  api.MapPost("/auth/cadastro",async(Cadastro i,Contas service)=>{await service.Cadastrar(i);return Results.Created("/api/me",new{mensagem="Conta criada."});}).RequireRateLimiting("auth");
  api.MapPost("/auth/login",async(Login i,Contas service,HttpContext c)=>{var s=await service.Entrar(i);if(i.Cliente=="web")c.Response.Cookies.Append(SessionAuth.Cookie,s.Token!,new CookieOptions{HttpOnly=true,Secure=c.Request.IsHttps,SameSite=SameSiteMode.Strict,Path="/",Expires=new DateTimeOffset(s.ExpiraEm)});return s with{Token=i.Cliente=="app"?s.Token:null};}).RequireRateLimiting("auth");
  api.MapPost("/auth/logout",async(ClaimsPrincipal u,AppDb db,HttpContext c)=>{var hash=u.FindFirstValue("sessao");await db.Sessoes.Where(x=>x.Hash==hash).ExecuteDeleteAsync();c.Response.Cookies.Delete(SessionAuth.Cookie,new CookieOptions{Path="/"});return Results.NoContent();}).RequireAuthorization();
  api.MapGet("/animais",async(AppDb db,string? busca,string? especie,string? porte,string? status,int pagina=1,int tamanho=12)=>{
   pagina=Math.Clamp(pagina,1,1000000);tamanho=Math.Clamp(tamanho,1,50);var q=db.Animais.AsNoTracking().Where(x=>!x.Arquivado);
   if(!string.IsNullOrWhiteSpace(busca)){var term=busca.Trim();q=q.Where(x=>x.Nome.Contains(term)||x.Raca.Contains(term));}
   if(!string.IsNullOrEmpty(especie))q=q.Where(x=>x.Especie==especie);if(!string.IsNullOrEmpty(porte))q=q.Where(x=>x.Porte==porte);if(!string.IsNullOrEmpty(status))q=q.Where(x=>x.Status==status);
   var total=await q.CountAsync();var items=await q.OrderBy(x=>x.Nome).ThenBy(x=>x.Id).Skip((pagina-1)*tamanho).Take(tamanho).ToListAsync();return new Pagina<AnimalDto>(items.Select(AnimalDto).ToArray(),total,pagina,tamanho);
  });
  api.MapGet("/animais/{id:int}",async(int id,AppDb db)=>{var a=await db.Animais.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&!x.Arquivado);return a is null?Results.NotFound():Results.Ok(AnimalDto(a));});
  api.MapGet("/fotos/{name}",(string name,Fotos fotos,CancellationToken ct)=>fotos.Ler(name,ct));
  var me=api.MapGroup("/me").RequireAuthorization();
  me.MapGet("/",(ClaimsPrincipal u,Contas s)=>s.Perfil(u.Id()));me.MapPut("/",(PerfilInput i,ClaimsPrincipal u,Contas s)=>s.Atualizar(u.Id(),i));
  me.MapPut("/senha",async(SenhaInput i,ClaimsPrincipal u,Contas s,HttpContext c)=>{await s.Senha(u.Id(),i);c.Response.Cookies.Delete(SessionAuth.Cookie);return Results.NoContent();}).RequireRateLimiting("auth");
  me.MapGet("/recomendacoes",async(ClaimsPrincipal u,AppDb db)=>{var p=await db.Adotantes.SingleAsync(x=>x.UsuarioId==u.Id());var animals=await db.Animais.AsNoTracking().Where(x=>!x.Arquivado&&x.Status=="disponivel").ToListAsync();return animals.Select(a=>AnimalDto(a) with{Compatibilidade=Regras.Afinidade(a,p.EspeciePreferida,p.Espaco,p.Experiencia)}).OrderByDescending(x=>x.Compatibilidade).ThenBy(x=>x.Nome).Take(12);});
  me.MapGet("/adocoes",async(ClaimsPrincipal u,AppDb db)=>{var id=u.Id();var items=await db.Adocoes.AsNoTracking().Include(x=>x.Animal).Where(x=>x.Adotante.UsuarioId==id).OrderByDescending(x=>x.CriadoEm).ToListAsync();return items.Select(a=>Adocoes.Dto(a));});
  me.MapPost("/adocoes",async(AdocaoInput i,ClaimsPrincipal u,Adocoes s)=>Results.Created("/api/me/adocoes",await s.Criar(u.Id(),i)));
  me.MapPost("/adocoes/{id:int}/cancelar",async(int id,ClaimsPrincipal u,Adocoes s)=>{await s.Alterar(id,"cancelada",u.Id(),false);return Results.NoContent();});
  me.MapGet("/doacoes",async(ClaimsPrincipal u,AppDb db)=>{var id=u.Id();return (await db.Doacoes.AsNoTracking().Where(x=>x.Adotante.UsuarioId==id).OrderByDescending(x=>x.CriadoEm).ToListAsync()).Select(d=>DoacaoDto(d));});
  me.MapPost("/doacoes",async(DoacaoInput i,ClaimsPrincipal u,AppDb db)=>{Regras.Validar(i);Regras.Opcao(i.FormaPagamento,"pix","transferencia","dinheiro");Regras.Exigir(decimal.Round(i.Valor,2)==i.Valor,"Use até duas casas decimais.");var a=await db.Adotantes.SingleAsync(x=>x.UsuarioId==u.Id());var d=new Doacao{AdotanteId=a.Id,Valor=i.Valor,FormaPagamento=i.FormaPagamento,Descricao=Regras.Limpar(i.Descricao),Anonima=i.Anonima};db.Doacoes.Add(d);await db.SaveChangesAsync();return Results.Created("/api/me/doacoes",DoacaoDto(d));});
  me.MapPost("/doacoes/{id:int}/cancelar",async(int id,ClaimsPrincipal u,AppDb db)=>{await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var uid=u.Id();var d=await db.Doacoes.SingleOrDefaultAsync(x=>x.Id==id&&x.Adotante.UsuarioId==uid)??throw new RegraException("Doação não encontrada.",404);Regras.Exigir(d.Status=="pendente","Somente intenções pendentes podem ser canceladas.",409);d.Status="cancelada";await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
  me.MapGet("/voluntariado",async(ClaimsPrincipal u,AppDb db)=>{var uid=u.Id();var v=await db.Voluntarios.AsNoTracking().SingleOrDefaultAsync(x=>x.UsuarioId==uid);return Results.Json(v is null?null:VoluntarioDto(v));});
  me.MapPut("/voluntariado",async(VoluntarioInput i,ClaimsPrincipal u,AppDb db)=>{Regras.Validar(i);Regras.Exigir(!string.IsNullOrWhiteSpace(i.Area)&&!string.IsNullOrWhiteSpace(i.Disponibilidade),"Informe área e disponibilidade.");var uid=u.Id();var v=await db.Voluntarios.SingleOrDefaultAsync(x=>x.UsuarioId==uid);if(v is null){v=new Voluntario{UsuarioId=uid};db.Voluntarios.Add(v);}v.Area=i.Area.Trim();v.Disponibilidade=i.Disponibilidade.Trim();if(v.Status=="inativo")v.Status="pendente";await db.SaveChangesAsync();return VoluntarioDto(v);});
  me.MapDelete("/voluntariado",async(ClaimsPrincipal u,AppDb db)=>{var uid=u.Id();var v=await db.Voluntarios.SingleOrDefaultAsync(x=>x.UsuarioId==uid);if(v is not null){v.Status="inativo";await db.SaveChangesAsync();}return Results.NoContent();});
  MapAdmin(api);
 }
 static void MapAdmin(RouteGroupBuilder api){
  var admin=api.MapGroup("/admin").RequireAuthorization("AdminWeb");
  admin.MapGet("/resumo",async(AppDb db)=>new ResumoDto(await db.Animais.CountAsync(x=>!x.Arquivado&&x.Status=="disponivel"),await db.Adocoes.CountAsync(x=>x.Status=="pendente"),await db.Adocoes.CountAsync(x=>x.Status=="concluida"),(await db.Doacoes.Where(x=>x.Status=="confirmada").Select(x=>x.Valor).ToListAsync()).Sum(),await db.Voluntarios.CountAsync(x=>x.Status=="ativo")));
  admin.MapPost("/animais",async(AnimalInput i,AppDb db)=>{Regras.Animal(i);Regras.Opcao(i.Status,"disponivel","em_tratamento");var a=new Animal();Copy(a,i);db.Animais.Add(a);await db.SaveChangesAsync();return Results.Created("/api/animais/"+a.Id,AnimalDto(a));});
  admin.MapPut("/animais/{id:int}",async(int id,AnimalInput i,AppDb db)=>{Regras.Animal(i);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var a=await db.Animais.SingleOrDefaultAsync(x=>x.Id==id&&!x.Arquivado)??throw new RegraException("Animal não encontrado.",404);if(a.Status!=i.Status){Regras.Exigir((a.Status is "disponivel" or "em_tratamento")&&(i.Status is "disponivel" or "em_tratamento"),"Altere o status pelo processo de adoção.",409);Regras.Exigir(!await db.Adocoes.AnyAsync(x=>x.AnimalId==id&&x.Ativa),"Animal com adoção ativa.",409);}Copy(a,i);await db.SaveChangesAsync();await tx.CommitAsync();return AnimalDto(a);});
  admin.MapPost("/animais/{id:int}/foto",async(int id,HttpRequest request,AppDb db,Fotos fotos,CancellationToken ct)=>{var a=await db.Animais.SingleOrDefaultAsync(x=>x.Id==id&&!x.Arquivado,ct)??throw new RegraException("Animal não encontrado.",404);Regras.Exigir(request.HasFormContentType,"Envie a foto como formulário.");var form=await request.ReadFormAsync(ct);var f=form.Files.GetFile("foto")??throw new RegraException("Selecione uma foto.");a.FotoUrl=await fotos.Salvar(f,ct);await db.SaveChangesAsync(ct);return AnimalDto(a);});
  admin.MapDelete("/animais/{id:int}",async(int id,AppDb db)=>{await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var a=await db.Animais.SingleOrDefaultAsync(x=>x.Id==id)??throw new RegraException("Animal não encontrado.",404);Regras.Exigir(!await db.Adocoes.AnyAsync(x=>x.AnimalId==id&&x.Ativa),"Finalize ou cancele a adoção antes de arquivar.",409);a.Arquivado=true;await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
  admin.MapGet("/adotantes",async(AppDb db,int pagina=1)=>{pagina=Math.Clamp(pagina,1,1000000);var q=db.Adotantes.AsNoTracking().Include(x=>x.Usuario);var items=await q.OrderBy(x=>x.Id).Skip((pagina-1)*50).Take(50).ToListAsync();return new{itens=items.Select(x=>new{x.Id,x.Usuario.Nome,x.Usuario.Email,x.Usuario.Telefone,x.Usuario.Endereco,Cpf=x.Usuario.Cpf is null?null:"***.***.***-"+x.Usuario.Cpf[^2..]}),total=await q.CountAsync(),paginaAtual=pagina,tamanho=50};});
  admin.MapGet("/adocoes",async(AppDb db,int pagina=1)=>{pagina=Math.Clamp(pagina,1,1000000);var q=db.Adocoes.AsNoTracking().Include(x=>x.Animal).Include(x=>x.Adotante).ThenInclude(x=>x.Usuario);var items=await q.OrderByDescending(x=>x.CriadoEm).Skip((pagina-1)*50).Take(50).ToListAsync();return new Pagina<AdocaoDto>(items.Select(x=>Adocoes.Dto(x,true)).ToArray(),await q.CountAsync(),pagina,50);});
  admin.MapPut("/adocoes/{id:int}/status",async(int id,StatusInput i,ClaimsPrincipal u,Adocoes s)=>{await s.Alterar(id,i.Status,u.Id(),true);return Results.NoContent();});
  admin.MapGet("/doacoes",async(AppDb db,int pagina=1)=>{pagina=Math.Clamp(pagina,1,1000000);var q=db.Doacoes.AsNoTracking().Include(x=>x.Adotante).ThenInclude(x=>x.Usuario);var items=await q.OrderByDescending(x=>x.CriadoEm).Skip((pagina-1)*50).Take(50).ToListAsync();return new Pagina<DoacaoDto>(items.Select(x=>DoacaoDto(x,true)).ToArray(),await q.CountAsync(),pagina,50);});
  admin.MapPut("/doacoes/{id:int}/status",async(int id,StatusInput i,ClaimsPrincipal u,AppDb db)=>{Regras.Opcao(i.Status,"confirmada","cancelada");await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var d=await db.Doacoes.SingleOrDefaultAsync(x=>x.Id==id)??throw new RegraException("Doação não encontrada.",404);Regras.Exigir(d.Status=="pendente","Registro já finalizado.",409);d.Status=i.Status;db.Auditorias.Add(new Auditoria{UsuarioId=u.Id(),Acao="doação: "+i.Status,Entidade="Doacoes",RegistroId=id});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
  admin.MapGet("/voluntarios",async(AppDb db,int pagina=1)=>{pagina=Math.Clamp(pagina,1,1000000);var q=db.Voluntarios.AsNoTracking().Include(x=>x.Usuario);var items=await q.OrderByDescending(x=>x.CriadoEm).Skip((pagina-1)*50).Take(50).ToListAsync();return new Pagina<VoluntarioDto>(items.Select(x=>VoluntarioDto(x,true)).ToArray(),await q.CountAsync(),pagina,50);});
  admin.MapPut("/voluntarios/{id:int}/status",async(int id,StatusInput i,AppDb db)=>{Regras.Opcao(i.Status,"pendente","ativo","inativo");var v=await db.Voluntarios.SingleOrDefaultAsync(x=>x.Id==id)??throw new RegraException("Voluntário não encontrado.",404);v.Status=i.Status;await db.SaveChangesAsync();return Results.NoContent();});
 }
 static void Copy(Animal a,AnimalInput i){a.Nome=i.Nome.Trim();a.Especie=i.Especie;a.Raca=Regras.Limpar(i.Raca);a.Idade=i.Idade;a.Porte=i.Porte;a.Status=i.Status;a.Descricao=Regras.Limpar(i.Descricao);}
}
